<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { anularSolicitud, conexionesCliente, detalleSolicitud, listarSolicitudes, registrarSolicitud } from '../services/solicitudes'
import type { Option, Options, Solicitud } from '../interfaces/solicitudes.interface'
const rows=ref<Solicitud[]>([]),options=ref<Options>({conceptos:[],distritos:[],clientes:[],conexiones:[],estados:[]}),connections=ref<Option[]>([]),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<Solicitud|null>(null),clientSearch=ref('')
const filters=reactive({criterio:'',concepto_id:'',estado:'',desde:'',hasta:'',page:1}),form=reactive({cliente_id:'',concepto_id:'',conexion_id:'',distrito_id:'',direccion:'',referencia:'',observacion:''})
const clients=computed(()=>options.value.clientes.filter(x=>!clientSearch.value||x.nombre.toLowerCase().includes(clientSearch.value.toLowerCase())).slice(0,30)),concept=computed(()=>options.value.conceptos.find(x=>String(x.id)===String(form.concepto_id)))
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarSolicitudes(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;options.value=r.options}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(){Object.assign(form,{cliente_id:'',concepto_id:'',conexion_id:'',distrito_id:'',direccion:'',referencia:'',observacion:''});connections.value=[];clientSearch.value='';modal.value=true}async function selectClient(id:number){form.cliente_id=String(id);try{connections.value=await conexionesCliente(id)}catch{connections.value=[]}}
async function save(){if(!form.cliente_id||!form.concepto_id||!form.distrito_id||!form.direccion||!form.referencia){error.value='Complete el cliente, tipo, distrito, dirección y referencia.';return}if(concept.value?.requiere_conexion&&!form.conexion_id){error.value='Este tipo de solicitud requiere seleccionar una conexión.';return}saving.value=true;error.value='';try{const r=await registrarSolicitud(form);modal.value=false;success.value='Solicitud registrada y flujo iniciado correctamente.';detail.value=await detalleSolicitud(r.id);await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:Solicitud){try{detail.value=await detalleSolicitud(item.id)}catch(e){error.value=message(e)}}async function remove(item:Solicitud){if(!confirm(`¿Anular la solicitud ${item.numero||'#'+item.id}?`))return;try{await anularSolicitud(item.id);success.value='Solicitud anulada correctamente.';detail.value=null;await load()}catch(e){error.value=message(e)}}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Solicitudes</nav><header class="hero"><div class="mark">SL</div><div><small>EVAN · COMERCIALIZACIÓN</small><h1>Solicitudes comerciales</h1><p>Registro y seguimiento del flujo de atención solicitado por el cliente.</p></div><strong>{{total}} solicitudes</strong><button @click="open">+ Nueva solicitud</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Número, cliente, DNI o dirección" @keyup.enter="load(1)"></label><label>Tipo<select v-model="filters.concepto_id"><option value="">Todos</option><option v-for="x in options.conceptos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="x in options.estados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando solicitudes…</div><div v-else-if="!rows.length" class="empty">No se encontraron solicitudes.</div>
<section v-else class="table"><header><span>Solicitud</span><span>Cliente</span><span>Tipo</span><span>Ubicación</span><span>Fase actual</span><span>Estado</span><span>Registro</span><span></span></header><article v-for="item in rows" :key="item.id"><b>{{item.numero||'#'+String(item.id).padStart(6,'0')}}</b><div><b>{{item.cliente}}</b><small>{{item.documento}}</small></div><span>{{item.concepto}}</span><div><b>{{item.distrito}}</b><small>{{item.direccion}}</small></div><span>{{item.fase_actual||'Sin iniciar'}}</span><em>{{item.estado}}</em><time>{{item.fecha_registro}}</time><footer><button @click="show(item)">Ver</button><button v-if="item.puede_anular" class="danger" @click="remove(item)">Anular</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>NUEVO REGISTRO</small><h2>Registrar solicitud</h2></div><button type="button" @click="modal=false">×</button></header><h3>1. Seleccionar cliente</h3><input v-model.trim="clientSearch" placeholder="Buscar cliente por nombre o documento"><div class="selector"><button v-for="x in clients" :key="x.id" type="button" :class="{selected:String(x.id)===form.cliente_id}" @click="selectClient(x.id)"><b>{{x.nombre}}</b><em>{{String(x.id)===form.cliente_id?'✓':''}}</em></button></div><h3>2. Tipo y ubicación</h3><div class="grid"><label>Tipo de solicitud *<select v-model="form.concepto_id"><option value="">Seleccione</option><option v-for="x in options.conceptos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label v-if="concept?.requiere_conexion">Conexión *<select v-model="form.conexion_id"><option value="">Seleccione</option><option v-for="x in connections" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Distrito *<select v-model="form.distrito_id"><option value="">Seleccione</option><option v-for="x in options.distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Dirección *<input v-model.trim="form.direccion"></label><label>Referencia *<input v-model.trim="form.referencia"></label></div><label>Detalle de la conexión o solicitud<textarea v-model.trim="form.observacion" rows="5"></textarea></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar e iniciar flujo'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>FICHA DE SOLICITUD</small><h2>{{detail.numero||'Solicitud #'+detail.id}}</h2><p>{{detail.cliente}} · {{detail.documento}}</p></div><button @click="detail=null">×</button></header><div class="summary"><div><b>{{detail.concepto}}</b><span>Tipo</span></div><div><b>{{detail.estado}}</b><span>Estado</span></div><div><b>{{detail.fase_actual||'—'}}</b><span>Fase actual</span></div><div><b>{{detail.responsable||'Sin asignar'}}</b><span>Responsable</span></div></div><p class="address"><b>{{detail.distrito}} · {{detail.direccion}}</b><br>{{detail.referencia}}<br>{{detail.observacion}}</p><h3>Flujo de atención</h3><div class="timeline"><article v-for="phase in detail.fases" :key="phase.id" :class="phase.estado.toLowerCase().replaceAll(' ','-')"><b>{{phase.secuencia}}. {{phase.nombre}}</b><span>{{phase.estado}}</span><small>{{phase.responsable||'Sin responsable'}} · {{phase.fecha_inicio||'Pendiente'}}</small></article></div><footer><button class="clear" @click="detail=null">Cerrar</button><button v-if="detail.puede_anular" class="danger-bg" @click="remove(detail)">Anular solicitud</button></footer></section></div></div></template>
<style scoped>
.page{--accent:#21a06b;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:7px;border-radius:9px;background:#fff}.filters label{flex:1;font-size:.53rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.6rem}.table{margin-top:13px;border-radius:9px;background:#fff;overflow:hidden}.table>header,.table>article{padding:10px 12px;display:grid;grid-template-columns:90px 1.2fr 1.2fr 1.2fr 1fr 80px 100px 70px;align-items:center;gap:7px}.table>header{color:#fff;background:var(--accent);font-size:.5rem;font-weight:700}.table>article{border-bottom:1px solid #edf0f2;font-size:.53rem}.table small{display:block;color:#7d898f}.table em{padding:4px;border-radius:9px;background:#eff9f4;font-style:normal;text-align:center}.table footer button{border:0;color:var(--accent);background:none;font-size:.49rem}.table footer .danger{color:#a13f43}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,800px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal h3{font-size:.65rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.selector{max-height:130px;margin:6px 0 14px;overflow:auto}.selector button{width:100%;padding:7px;display:flex;justify-content:space-between;border:0;border-bottom:1px solid #e8ecee;background:#fff;text-align:left;font-size:.53rem}.selector button.selected{background:#eff9f4}.selector em{color:var(--accent)}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.danger-bg{background:#a13f43!important}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.summary div{padding:11px;text-align:center;border-radius:7px;background:#eff9f4}.summary b,.summary span{display:block;font-size:.53rem}.address{padding:11px;border-left:3px solid var(--accent);background:#f6f8f9;font-size:.56rem}.timeline article{padding:9px 10px;border-left:3px solid #ccd5d9;border-bottom:1px solid #edf0f2;font-size:.54rem}.timeline article b,.timeline article small{display:block}.timeline article span{float:right}.timeline article.finalizado{border-color:var(--accent)}.detail{width:min(100%,900px)}@media(max-width:950px){.table>header{display:none}.table>article{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.table>article,.grid,.summary{grid-template-columns:1fr}}
</style>
